import{_ as t,o as n,c as o,a0 as r}from"./chunks/framework.BWpMpcZ2.js";const u=JSON.parse('{"title":"Agent Harnesses","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/harnesses.md","filePath":"configuration/harnesses.md"}'),a={name:"configuration/harnesses.md"};function s(i,e,l,h,d,g){return n(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="agent-harnesses" tabindex="-1">Agent Harnesses <a class="header-anchor" href="#agent-harnesses" aria-label="Permalink to &quot;Agent Harnesses&quot;">​</a></h1><p>If you already pay for an AI coding helper, Margin can use it instead of an API endpoint. The helper runs on your computer, edits your files, and Margin shows you what changed.</p><table tabindex="0"><thead><tr><th>Helper</th><th>Notes</th></tr></thead><tbody><tr><td><strong>OpenCode</strong></td><td>Model list comes straight from the helper.</td></tr><tr><td><strong>Claude Code</strong></td><td>Built-in model list[^1] — or type any model name by hand.</td></tr><tr><td><strong>Codex</strong></td><td>Built-in model list[^1] — or type any model name by hand.</td></tr><tr><td><strong>Antigravity</strong></td><td>Model list comes straight from the helper.</td></tr></tbody></table><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Install the helper and sign in using its own instructions, in your own terminal. Margin only starts the helper&#39;s program — it never sees or stores your sign-in. If a run fails with a sign-in error, the helper&#39;s own message is shown; sign in again in your terminal and retry.</p><h2 id="finding-your-helpers" tabindex="-1">Finding your helpers <a class="header-anchor" href="#finding-your-helpers" aria-label="Permalink to &quot;Finding your helpers&quot;">​</a></h2><p><strong>Settings &gt; Harnesses</strong> lists each supported helper:</p><ul><li><code>✓ Ready · &lt;version&gt;</code> — good to go.</li><li><code>✕ Not installed</code> — install and sign in to its program, then reopen Settings and it should appear.</li></ul><p>If Margin can&#39;t find a helper you installed, enter its location by hand in the &quot;Custom program&quot; box for that helper.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><ul><li><strong>Default Harness</strong>: <code>None — use endpoint</code> (the normal setting — nothing changes) or one of your helpers. You can also pick a helper per message from the dropdown in the Assist panel; the inline bubble always follows the default.</li><li><strong>Default model</strong>: which model the helper should use. OpenCode and Antigravity show the list straight from the helper itself. Codex and Claude Code don&#39;t offer a list command, so Margin ships a built-in list for them[^1] — or just type any model name by hand.</li><li><strong>Custom program</strong>: the helper&#39;s location on your computer, for installs Margin can&#39;t find on its own.</li><li><strong>Ctx</strong>: the helper model&#39;s context window, used only for the usage ring next to the input. Leave empty to hide the ring — the token count still shows.</li><li><strong>Harness Edit prompt</strong>: the standing edit instructions (including the rule that changes land in files, not in the reply) are editable in <strong>Settings &gt; Context</strong> — see <a href="./prompts.html">Prompts</a>.</li></ul><p>[^1]: The built-in lists for Codex and Claude Code are updated with Margin releases. If a brand-new model is missing, type its name by hand.</p><h2 id="token-counts" tabindex="-1">Token counts <a class="header-anchor" href="#token-counts" aria-label="Permalink to &quot;Token counts&quot;">​</a></h2><p>The input bar always shows session token totals. All four helpers report real usage; if a run reports none, Margin estimates from text length (<code>len/4</code>) — treated as approximate. The <code>%</code> ring appears only when a context window is known (the Ctx field above).</p><h2 id="while-it-works" tabindex="-1">While it works <a class="header-anchor" href="#while-it-works" aria-label="Permalink to &quot;While it works&quot;">​</a></h2><ul><li>You can keep writing — the editor never locks.</li><li>The helper&#39;s progress appears in the panel as it works: text and reasoning as it streams, plus one line per file read, edited, or created.</li><li>When it finishes, its changes are highlighted in your document. Conflicts (you edited the same paragraph) keep your version and are flagged.</li><li><strong>Accept</strong> keeps the merged result; <strong>Reject</strong> removes the helper&#39;s changes but preserves yours.</li></ul><h2 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-label="Permalink to &quot;If something goes wrong&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you see</th><th>What to do</th></tr></thead><tbody><tr><td><code>&lt;Name&gt; not found</code></td><td>Install the helper&#39;s program, or enter its location in Settings &gt; Harnesses.</td></tr><tr><td>Sign-in / login errors</td><td>Sign in to the helper in your terminal and retry.</td></tr><tr><td>The helper changed other files</td><td>Only the open file is merged and highlighted. Other files appear in the sidebar as the helper saves them — live for all four helpers.</td></tr></tbody></table>',18)])])}const c=t(a,[["render",s]]);export{u as __pageData,c as default};
